<!-- Header Section -->
<table class="print-header">
    <tr>
        <td style="width: 33.3%;"><b>Reference Number:</b> {{ doc.name }}</td>
        <td style="width: 33.3%;"><b>Date of Creation:</b> {{ doc.creation }}</td>
        <td style="width: 33.3%;"><b>Created By:</b> {{ doc.owner }}</td>
    </tr>
</table>

