[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "<div></div>"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": " <style>
        /* Global Styles */
        body {
            font-family: Arial, sans-serif;
            margin: 0;
            padding: 0;
            color: #000;
        }
        .container {
            width: 95%;
            margin: 0 auto;
        }
        /* Table Styles */
        .header-table {
            width: 100%;
            border-collapse: collapse;
            margin-bottom: 20px;
        }
        .header-table td {
            border: 1px solid grey;
            padding: 5px;
            vertical-align: top;
        }
        .header-table tr:nth-child(even) {
            background-color: #D3E6EA;
        }
        .header-title {
            background-color: #16a7aa;
            color: white;
            font-size: 25px;
            text-align: center;
            padding: 10px !important;
        }
        /* Section Styles */
        .section {
            margin: 30px auto;
            page-break-inside: avoid;
        }
        .section-title {
            font-weight: bold;
            font-size: 16px;
            margin-bottom: 10px;
        }
        .content-table {
            width: 100%;
            border-collapse: collapse;
        }
        .content-table td {
            border: 1px solid grey;
            padding: 5px;
        }
        .content-table tr:nth-child(even) {
            background-color: #D3E6EA;
        }
        .table-header {
            background-color: #16a7aa;
            color: white;
            font-weight: bold;
        }
        .summary-row {
            background-color: #9FBEC4 !important;
            font-weight: bold;
        }
        /* Utility Classes */
        .text-center {
            text-align: center;
        }
        .text-right {
            text-align: right;
        }
        /* Footer Styles */
        .footer {
            width: 100%;
            text-align: center;
            margin-top: 30px;
            font-size: 12px;
        }
    </style>
    <!-- Header with Logo -->
    <div style="width:100%;text-align:center;margin-top:20px;">
        <img src="/files/Kayan Logo.jpg" style="width:350px;height:500px;">
    </div>

    <!-- Main Proposal Content -->
    <div class="container">
        <!-- Proposal Header Table -->
        <table class="header-table">
            <tr>
                <td colspan="4" class="header-title">COMMERCIAL PROPOSAL</td>
            </tr>
            <tr>
                <td>Client:</td>
                <td colspan="3">{{ doc.customer_name or '' }}</td>
            </tr>
            <tr>
                <td>Attention:</td>
                <td>{{ doc.contact_display or '' }}</td>
                <td>Designation:</td>
                <td>
                    {% if doc.contact_person %}
                        {% set des = frappe.db.get_value("Contact", doc.contact_person, "designation") %}
                        {{ des or '' }}
                    {% endif %}
                </td>
            </tr>
            <tr>
                <td>Contact Mobile:</td>
                <td>{{ doc.contact_mobile or '' }}</td>
                <td>Contact Email:</td>
                <td>{{ doc.contact_email or '' }}</td>
            </tr>
            {% set project = frappe.get_doc("Project", doc.custom_project_name) if doc.custom_project_name else None %}
            <tr>
                <td>Project Name:</td>
                <td colspan="3">{{ project.project_name if project else '' }}</td>
            </tr>
            <tr>
                <td>Ref. No:</td>
                <td colspan="3">{{ doc.custom_project_name or '' }}</td>
            </tr>
            <tr>
                <td>Quotation No:</td>
                <td>{{ doc.name }}</td>
                <td>Date:</td>
                <td>{{ doc.transaction_date or '' }}</td>
            </tr>
            <tr>
                <td>Offered by:</td>
                <td>
                    {% if doc.custom_sales_engineer %}
                        {% set emp_name = frappe.db.get_value("Employee", doc.custom_sales_engineer, "employee_name") %}
                        {{ emp_name or '' }}
                    {% endif %}
                </td>
                <td>Designation:</td>
                <td>
                    {% if doc.custom_sales_engineer %}
                        {% set emp_des = frappe.db.get_value("Employee", doc.custom_sales_engineer, "designation") %}
                        {{ emp_des or '' }}
                    {% endif %}
                </td>
            </tr>
            <tr>
                <td>Mobile No.:</td>
                <td>
                    {% if doc.custom_sales_engineer %}
                        {% set emp_mob = frappe.db.get_value("Employee", doc.custom_sales_engineer, "cell_number") %}
                        {{ emp_mob or '' }}
                    {% endif %}
                </td>
                <td>Email:</td>
                <td>
                    {% if doc.custom_sales_engineer %}
                        {% set emp_email = frappe.db.get_value("Employee", doc.custom_sales_engineer, "company_email") %}
                        {{ emp_email or '' }}
                    {% endif %}
                </td>
            </tr>
        </table>

        <!-- Signature Section -->
        <div style="width:98%;margin:30px auto 10px;page-break-before: always;">
            <p><u><b>Signature</b></u></p>
        </div>

        <!-- 1. Scope of Project -->
        <div class="section">
            <div class="section-title">1 - Scope</div>
            <table class="content-table">
                <tr class="table-header">
                    <td style="width:5%;text-align:center;">#</td>
                    <td>Scope of Project</td>
                </tr>
                {% for excl in doc.custom_scope_of_the_project %}
                <tr>
                    <td style="text-align:center;">{{ loop.index }}</td>
                    <td>{{ excl.scope_project }}</td>
                </tr>
                {% endfor %}
            </table>
        </div>

        <!-- 2. Commercial Offer -->
        <div class="section">
            <div class="section-title">2 - COMMERCIAL OFFER</div>
            <table class="content-table">
                <tr class="table-header">
                    <td style="width:5%;text-align:center;">#</td>
                    <td style="width:50%;">Description</td>
                    <td style="width:5%;text-align:center;">Unit</td>
                    <td style="width:10%;text-align:center;">Qty</td>
                    <td style="width:15%;text-align:center;">Unit Price</td>
                    <td style="width:15%;text-align:center;">Amount</td>
                </tr>
                {% for item in doc.items %}
                <tr>
                    <td style="text-align:center;">{{ item.idx }}</td>
                    <td>{{ item.description }}</td>
                    <td style="text-align:center;">{{ item.uom }}</td>
                    <td style="text-align:center;">{{ item.qty }}</td>
                    <td style="text-align:right;">{{ "{:,.2f}".format(item.rate) }}</td>
                    <td style="text-align:right;">{{ "{:,.2f}".format(item.amount) }}</td>
                </tr>
                {% endfor %}
                <tr class="summary-row">
                    <td colspan="3" class="text-center">INTERIOR</td>
                    <td colspan="3"></td>
                </tr>
                <tr class="summary-row">
                    <td colspan="3" class="text-center">EXTERIOR</td>
                    <td colspan="3"></td>
                </tr>
                <tr class="summary-row">
                    <td colspan="3" class="text-center">DISCOUNT</td>
                    <td colspan="3" class="text-right">{{ "{:,.2f}".format(doc.discount_amount or 0) }}</td>
                </tr>
                <tr class="summary-row">
                    <td colspan="3" class="text-center">VAT</td>
                    <td colspan="3" class="text-right">{{ "{:,.2f}".format(doc.total_taxes_and_charges or 0) }}</td>
                </tr>
                <tr class="summary-row">
                    <td colspan="3" class="text-center"><b>TOTAL</b></td>
                    <td class="text-center"><b>{{ doc.items | sum(attribute='qty') }}</b></td>
                    <td></td>
                    <td class="text-right"><b>{{ "{:,.2f}".format(doc.grand_total) }}</b></td>
                </tr>
            </table>
            {% if not doc.total_taxes_and_charges or doc.total_taxes_and_charges == 0 %}
                <p style="text-align:right;"><u>Price above by Saudi Riyal and Excluding VAT.</u></p>
            {% endif %}
        </div>

        <!-- 3. Mobilization -->
        <div class="section">
            <div class="section-title">3 - Mobilization</div>
            <table class="content-table">
                <tr class="table-header">
                    <td>Descriptions</td>
                </tr>
                <tr>
                    <td>{{ doc.custom_terms_of_delivery }}</td>
                </tr>
            </table>
        </div>

        <!-- 4. Payment Terms -->
        <div class="section">
            <div class="section-title">4 - PAYMENT TERMS</div>
            <table class="content-table">
                <tr class="table-header">
                    <td style="width:80%;">Description</td>
                    <td style="width:20%;text-align:center;">Percentage</td>
                </tr>
                {% for pt in doc.payment_schedule %}
                <tr>
                    <td>{{ pt.description }}</td>
                    <td style="text-align:center;">{{ pt.invoice_portion }}</td>
                </tr>
                {% endfor %}
            </table>
        </div>

        <!-- 5. Exclusions -->
        <div class="section">
            <div class="section-title">5 - Exclusions</div>
            <table class="content-table">
                <tr class="table-header">
                    <td style="width:5%;text-align:center;">#</td>
                    <td>Exclusions</td>
                </tr>
                {% for excl in doc.custom_exclusions %}
                <tr>
                    <td style="text-align:center;">{{ loop.index }}</td>
                    <td>{{ excl.exclusion }}</td>
                </tr>
                {% endfor %}
            </table>
        </div>

        <!-- 6. Notes and Clarifications -->
        <div class="section">
            <div class="section-title">6 - Notes and Clarifications</div>
            <table class="content-table">
                <tr class="table-header">
                    <td style="width:5%;text-align:center;">#</td>
                    <td>Notes</td>
                </tr>
                {% for excl in doc.custom_notes_and_clarifications %}
                <tr>
                    <td style="text-align:center;">{{ loop.index }}</td>
                    <td>{{ excl.notes }}</td>
                </tr>
                {% endfor %}
            </table>
        </div>
    </div>"}]

