<!-- Company & Supplier Info Table -->
<table style="width:100%;border-collapse:collapse;border:1px solid black;font-size:9pt;">
    <tr>
        <td style="font-size:14px;font-weight:bold;text-align:center;width:50%;color:black;background-color:#16a7aa;line-height:1.2;border:1px solid black;padding:3px 6px;">Company</td>
        <td style="font-size:14px;font-weight:bold;text-align:center;width:50%;color:black;background-color:#16a7aa;line-height:1.2;border:1px solid black;padding:3px 6px;">Supplier</td>
