<!-- Items Table -->
<table style="width:100%;border:1px solid black;font-size:8pt;">
    <tr>
        <td style="width:3%;text-align:center;background-color:#16a7aa;border:1px solid black;">S.NO</td>
        <td style="width:13%;text-align:center;background-color:#16a7aa;border:1px solid black;">Item Code</td>
