<!-- Totals and Summary -->
{% set curr = doc.currency if doc.currency else "SAR" %}
<div style="width:100%;">
    <div style="width:33%;float:right;">
        <table style="width:100%;font-size:8pt;">
            <tr><td>Total</td><td style="text-align:right;">{{ curr }} {{ "{:,.2f}".format(doc.total) }}</td></tr>
            <tr><td>Discount</td><td style="text-align:right;">{{ curr }} {{ "{:,.2f}".format(doc.discount_amount) }}</td></tr>
