        /* Container for the entire form content */
        .container {
            width: 100%; /* Full width within the page margins */
            padding: 0;
            margin: 0 auto; /* Center the container */
            box-sizing: border-box;
        }

        /* Header section styling */
        .header {
            text-align: center;
            margin-bottom: 10px; /* Adjusted margin */
        }

        /* Company logo styling within the header */
        .header img.logo {
            max-height: 60px; /* Limit logo height */
            width: auto; /* Maintain aspect ratio */
        }

        /* Dual-language layout for side-by-side text */
        .dual-language {
            display: flex; /* Use flexbox for horizontal alignment */
            justify-content: space-between; /* Distribute space between items */
            align-items: flex-start; /* Align items to the top */
            margin-top: 10px; /* Adjusted margin */
        }

        /* Styling for English and Arabic content columns */
        .english, .arabic {
            width: 100%; /* Allocate 48% width to each column to leave a small gap */
            box-sizing: border-box; /* Include padding and border in the width */
        }

        /* Specific styling for Arabic text to ensure right-to-left direction */
        .arabic {
            text-align: right; /* Align Arabic text to the right */
            direction: rtl; /* Set text direction to right-to-left */
        }

        /* Section styling for logical grouping of form fields */
        .section {
            margin-top: 20px; /* Adjusted margin */
        }

        /* Title styling for each section */
        .section-title {
            font-weight: bold; /* Bold text for titles */
            margin-bottom: 5px; /* Adjusted margin */
            font-size: 1.1em; /* Slightly larger for emphasis */
        }

        /* Styling for individual form fields */
        .form-field {
            margin-top: 8px; /* Adjusted margin */
        }

        /* Styling for fields that require an underline for user input */
        .underline-field {
            display: inline-block; /* Allow width and padding to be set */
            min-width: 100px; /* Minimum width for the underline */
            border-bottom: 1px solid #000; /* Black underline */
            padding: 0 4px; /* Padding for text within the underline */
            margin: 0 5px; /* Margin around the underline field */
        }

        /* Styling for multi-line text areas */
        .text-area {
            min-height: 35px; /* Slightly increased min-height */
            padding: 4px 0; /* Vertical padding */
            border-bottom: 1px solid #000; /* Underline for the text area */
        }

        /* Styling for individual checkbox options */
        .checkbox-option {
            margin-bottom: 5px; /* Adjusted margin */
        }

        /* Signature area styling */
        .signature-area {
            margin-top: 25px; /* Adjusted margin */
        }

        /* Styling for each signature box (e.g., Requested By, Signature, Date) */
        .signature-box {
            margin-bottom: 10px; /* Adjusted margin */
        }

        /* Styling for the signature line */
        .signature-line {
            border-bottom: 1px solid #000; /* Black line for signature */
            min-width: 140px; /* Minimum width for the signature line */
            height: 20px; /* Slightly increased height */
            margin-top: 5px; /* Adjusted spacing above the line */
        }

        /* Footer styling */
        .footer {
            text-align: center;
            margin-top: 30px; /* Adjusted margin */
            font-style: italic; /* Italic text for the footer */
            font-size: 0.9em; /* Adjusted font size for footer text */
